const LESSONS = [{"id": "junior-be-verbs", "level": "junior", "order": 1, "title": "Be 動詞與自我介紹", "minutes": 15, "goals": ["用 am / is / are 說明身分與狀態。"], "vocabulary": [{"word": "student", "meaning": "學生"}, {"word": "ready", "meaning": "準備好的"}, {"word": "engineer", "meaning": "工程師"}], "grammar": "主詞 I 用 am；he / she / it 用 is；you / we / they 用 are。否定句在 be 動詞後加 not。", "examples": [{"en": "I am a student.", "zh": "我是一名學生。"}, {"en": "They are ready.", "zh": "他們準備好了。"}], "quiz": [{"question": "She ___ a student.", "options": ["am", "is", "are"], "answer": 1, "explanation": "She 是第三人稱單數，搭配 is。"}, {"question": "選出正確否定句。", "options": ["I not am ready.", "I am not ready.", "I do not ready."], "answer": 1, "explanation": "be 動詞的否定句直接在 be 後面加 not。"}], "task": ["用本課句型寫出兩句與自己生活或學習有關的英文。", "讀出自己的句子，檢查動詞與時間是否一致。"], "sources": [], "sourceNote": "本站自編教學例句與練習；階段為內容導覽，不代表正式能力分級或檢定認證。"}, {"id": "junior-present", "level": "junior", "order": 2, "title": "現在簡單式", "minutes": 15, "goals": ["描述習慣，並分辨第三人稱單數。"], "vocabulary": [{"word": "study", "meaning": "讀書"}, {"word": "usually", "meaning": "通常"}, {"word": "practice", "meaning": "練習"}], "grammar": "肯定句中，he / she / it 的一般動詞通常加 -s 或 -es；問句用 does 時，主要動詞回到原形。", "examples": [{"en": "I study English every day.", "zh": "我每天讀英文。"}, {"en": "Does he study English?", "zh": "他有讀英文嗎？"}], "quiz": [{"question": "He ___ English every day.", "options": ["study", "studies", "studying"], "answer": 1, "explanation": "第三人稱單數的 study 改成 studies。"}, {"question": "___ she play tennis?", "options": ["Do", "Does", "Is"], "answer": 1, "explanation": "一般動詞的第三人稱單數問句使用 Does。"}], "task": ["用本課句型寫出兩句與自己生活或學習有關的英文。", "讀出自己的句子，檢查動詞與時間是否一致。"], "sources": [], "sourceNote": "本站自編教學例句與練習；階段為內容導覽，不代表正式能力分級或檢定認證。"}, {"id": "junior-past", "level": "junior", "order": 3, "title": "過去式與時間", "minutes": 15, "goals": ["描述已經發生的事情。"], "vocabulary": [{"word": "yesterday", "meaning": "昨天"}, {"word": "visited", "meaning": "拜訪了"}, {"word": "went", "meaning": "去了"}], "grammar": "已結束的過去事件常使用過去式。規則動詞通常加 -ed；go 的過去式是 went。did 後使用原形動詞。", "examples": [{"en": "I visited my friend yesterday.", "zh": "我昨天拜訪了朋友。"}, {"en": "Did you go to school?", "zh": "你有去學校嗎？"}], "quiz": [{"question": "We ___ to Taipei yesterday.", "options": ["go", "went", "going"], "answer": 1, "explanation": "yesterday 表示過去，go 改為 went。"}, {"question": "Did he ___ the game?", "options": ["watched", "watch", "watches"], "answer": 1, "explanation": "did 已表達過去，後面使用原形 watch。"}], "task": ["用本課句型寫出兩句與自己生活或學習有關的英文。", "讀出自己的句子，檢查動詞與時間是否一致。"], "sources": [], "sourceNote": "本站自編教學例句與練習；階段為內容導覽，不代表正式能力分級或檢定認證。"}, {"id": "senior-perfect", "level": "senior", "order": 4, "title": "現在完成式", "minutes": 15, "goals": ["理解過去經驗與現在的關係。"], "vocabulary": [{"word": "experience", "meaning": "經驗"}, {"word": "already", "meaning": "已經"}, {"word": "since", "meaning": "自從"}], "grammar": "使用 have / has + 過去分詞，描述經驗或延續到現在的情況。若明確指出已結束的過去時間，通常改用過去簡單式。", "examples": [{"en": "I have visited Japan twice.", "zh": "我去過日本兩次。"}, {"en": "She has lived here since 2022.", "zh": "她自 2022 年起住在這裡。"}], "quiz": [{"question": "She ___ finished her homework.", "options": ["have", "has", "is"], "answer": 1, "explanation": "She 搭配 has，再接過去分詞 finished。"}, {"question": "選出適合 yesterday 的句子。", "options": ["I have seen him yesterday.", "I saw him yesterday.", "I see him yesterday."], "answer": 1, "explanation": "明確、已結束的過去時間搭配過去簡單式 saw。"}], "task": ["用本課句型寫出兩句與自己生活或學習有關的英文。", "讀出自己的句子，檢查動詞與時間是否一致。"], "sources": [], "sourceNote": "本站自編教學例句與練習；階段為內容導覽，不代表正式能力分級或檢定認證。"}, {"id": "senior-passive", "level": "senior", "order": 5, "title": "被動語態", "minutes": 15, "goals": ["分辨動作的執行者與接受者。"], "vocabulary": [{"word": "plant", "meaning": "種植"}, {"word": "design", "meaning": "設計"}, {"word": "build", "meaning": "建造"}], "grammar": "被動語態使用 be + 過去分詞。be 的時態隨語境改變；by 可引出動作執行者。", "examples": [{"en": "The flowers are planted by the students every spring.", "zh": "學生們每年春天種植這些花。"}, {"en": "The bridge was built in 1998.", "zh": "這座橋建於 1998 年。"}], "quiz": [{"question": "The bridge ___ built in 1998.", "options": ["is", "was", "has"], "answer": 1, "explanation": "1998 是過去時間，使用 was built。"}, {"question": "The report was written by Amy. 誰寫報告？", "options": ["Amy", "The report", "無法判斷"], "answer": 0, "explanation": "by Amy 指出動作執行者是 Amy。"}], "task": ["用本課句型寫出兩句與自己生活或學習有關的英文。", "讀出自己的句子，檢查動詞與時間是否一致。"], "sources": [], "sourceNote": "本站自編教學例句與練習；階段為內容導覽，不代表正式能力分級或檢定認證。"}, {"id": "senior-reading", "level": "senior", "order": 6, "title": "閱讀與因果連接", "minutes": 15, "goals": ["從連接詞辨識原因與結果。"], "vocabulary": [{"word": "because", "meaning": "因為"}, {"word": "therefore", "meaning": "因此"}, {"word": "improve", "meaning": "改善"}], "grammar": "because 引出原因；therefore 引出結果。閱讀時先找主旨，再找支持主旨的理由，不只翻譯單字。", "examples": [{"en": "I practice daily because I want to improve.", "zh": "我每天練習，因為我想進步。"}, {"en": "It rained heavily. Therefore, we stayed home.", "zh": "雨下得很大。因此我們待在家。"}], "quiz": [{"question": "I stayed home because I was sick. 留在家的原因？", "options": ["天氣好", "生病", "要運動"], "answer": 1, "explanation": "because 後面的 I was sick 是原因。"}, {"question": "哪個字常用來引出結果？", "options": ["although", "because", "therefore"], "answer": 2, "explanation": "therefore 表示「因此」，常引出結果。"}], "task": ["用本課句型寫出兩句與自己生活或學習有關的英文。", "讀出自己的句子，檢查動詞與時間是否一致。"], "sources": [], "sourceNote": "本站自編教學例句與練習；階段為內容導覽，不代表正式能力分級或檢定認證。"}, {"id": "college-summary", "level": "college", "order": 7, "title": "學術閱讀與摘要", "minutes": 15, "goals": ["區分主張、證據與摘要。"], "vocabulary": [{"word": "evidence", "meaning": "證據"}, {"word": "claim", "meaning": "主張"}, {"word": "summary", "meaning": "摘要"}], "grammar": "摘要應保留原文核心主張，用自己的話濃縮，避免加入原文沒有支持的結論。需要引用的內容要註明來源。", "examples": [{"en": "The study compares two learning methods.", "zh": "這項研究比較兩種學習方法。"}, {"en": "The results suggest a possible improvement.", "zh": "結果顯示可能有所改善。"}], "quiz": [{"question": "suggest a possible improvement 最接近哪個意思？", "options": ["已證明一定有效", "顯示可能有所改善", "完全沒有效果"], "answer": 1, "explanation": "suggest 和 possible 保留不確定性，不能改寫成確定有效。"}, {"question": "摘要應該怎麼寫？", "options": ["加入未驗證結論", "保留核心主張並濃縮", "整段照抄且不註來源"], "answer": 1, "explanation": "摘要濃縮核心意思，應保留原文的限制與不確定性。"}], "task": ["用本課句型寫出兩句與自己生活或學習有關的英文。", "讀出自己的句子，檢查動詞與時間是否一致。"], "sources": [], "sourceNote": "本站自編教學例句與練習；階段為內容導覽，不代表正式能力分級或檢定認證。"}, {"id": "college-email", "level": "college", "order": 8, "title": "正式 Email 與請求", "minutes": 15, "goals": ["使用有禮貌的句型提出具體請求。"], "vocabulary": [{"word": "request", "meaning": "請求"}, {"word": "deadline", "meaning": "截止時間"}, {"word": "attachment", "meaning": "附件"}], "grammar": "正式信件可依目的、背景、具體請求與致謝排列。Could you…? 適合禮貌請求；主旨應簡短明確。", "examples": [{"en": "Could you review my report by Friday?", "zh": "您能在週五前審閱我的報告嗎？"}, {"en": "Thank you for your time.", "zh": "感謝您撥冗。"}], "quiz": [{"question": "哪句較適合正式請求？", "options": ["Review it now!", "Could you review my report?", "Hey, do it."], "answer": 1, "explanation": "Could you…? 是較有禮貌的請求方式。"}, {"question": "哪個主旨較清楚？", "options": ["Hello", "Request for Feedback on My Report", "Something"], "answer": 1, "explanation": "主旨指出具體目的，讓收件者快速理解。"}], "task": ["用本課句型寫出兩句與自己生活或學習有關的英文。", "讀出自己的句子，檢查動詞與時間是否一致。"], "sources": [], "sourceNote": "本站自編教學例句與練習；階段為內容導覽，不代表正式能力分級或檢定認證。"}, {"id": "college-presentation", "level": "college", "order": 9, "title": "英文簡報與研究表達", "minutes": 15, "goals": ["用目的、方法與結果組織簡報。"], "vocabulary": [{"word": "objective", "meaning": "目標"}, {"word": "method", "meaning": "方法"}, {"word": "limitation", "meaning": "限制"}], "grammar": "先說明研究目的，再介紹方法與結果，最後指出限制。避免把相關性說成因果關係，或把模擬結果當成真實實驗。", "examples": [{"en": "The objective is to compare two methods.", "zh": "目標是比較兩種方法。"}, {"en": "These results are based on a simulation.", "zh": "這些結果來自模擬。"}], "quiz": [{"question": "研究簡報合理的順序？", "options": ["結果→閒聊→方法", "目的→方法→結果", "致謝→結果→不說目的"], "answer": 1, "explanation": "先交代目的，再說方法與結果，便於理解。"}, {"question": "模擬結果應如何說明？", "options": ["宣稱實測成功", "清楚標明來自模擬", "刪除所有限制"], "answer": 1, "explanation": "清楚區分模擬與實測，避免誇大證據。"}], "task": ["用本課句型寫出兩句與自己生活或學習有關的英文。", "讀出自己的句子，檢查動詞與時間是否一致。"], "sources": [], "sourceNote": "本站自編教學例句與練習；階段為內容導覽，不代表正式能力分級或檢定認證。"}];
